mapper.select:
SELECT COUNT(*)
FROM user_inventory ui
JOIN item i ON i.item_id = ui.item_id
AND i.category = 'BGM'
WHERE ui.user_id = #{userId}
AND ui.item_id = #{itemId}

mapper.update:
UPDATE minihompy
SET media_id = (
    SELECT media_id FROM media
    WHERE target_type = 'BGM' AND target_id = #{itemId}
)
WHERE user_id = #{userId}

UPDATE minihompy
SET media_id = NULL
WHERE user_id = #{userId}

mapper.select:
SELECT COUNT(*)
FROM minihompy
WHERE user_id = #{userId}
